import ProModules from './ProModules';
import {useEffect,useState} from 'react';
import type {ReactNode} from 'react';

type OrderStatus='planned'|'in_progress'|'done';type OpStatus='pending'|'in_progress'|'done';type Priority='low'|'medium'|'high';type ToolCondition='available'|'maintenance'|'unavailable';type ReservationStatus='reserved'|'in_use'|'released';
type TimeRecord={id:string;start:string;end:string;minutes:number};
type Operation={id:string;name:string;description:string;status:OpStatus;sequence:number;estimatedMinutes:number;manualMinutes:number;startedAt:string|null;timeRecords:TimeRecord[];machineId?:string|null;setupMinutes?:number;cycleMinutes?:number;hourlyRateOverride?:number|null;extraCost?:number};
type Assignment={id:string;materialId:string;quantity:number;consumed:boolean};
type WorkOrder={id:string;number:string;product:string;customer:string;description:string;quantity:number;startDate:string;deadline:string;priority:Priority;status:OrderStatus;notes:string;operations:Operation[];materialAssignments:Assignment[];createdAt:string;completedAt:string|null};
type Material={id:string;name:string;standard:string;shape:string;dimensions:string;quantity:number;unit:'kos'|'mm'|'m'|'kg';location:string};
type Tool={id:string;name:string;category:string;manufacturer:string;specification:string;size:string;location:string;condition:ToolCondition;notes:string};
type Machine={id:string;name:string;category:MachineCategory;code:string;manufacturer:string;hourlyRate:number;condition:ToolCondition;notes:string};
type MachineCategory='cnc_lathe'|'cnc_mill'|'manual_lathe'|'manual_mill'|'grinder'|'saw'|'drill'|'other';
type Reservation={id:string;toolId:string;workOrderId:string;operationId:string;status:ReservationStatus;reservedAt:string;releasedAt:string|null};
type Page='dashboard'|'orders'|'materials'|'tools'|'machines'|'archive'|'schedules'|'quotes'|'products'|'inspections'|'employees'|'drawings';
const API=`${window.location.protocol}//${window.location.hostname}:3001/api`;
const today=()=>new Date().toLocaleDateString('sv-SE');
const fmtDate=(s:string)=>s?new Date(s+'T12:00:00').toLocaleDateString('sl-SI'):'—';
const statusNames:Record<OrderStatus,string>={planned:'Načrtovan',in_progress:'V izdelavi',done:'Zaključen'};
const opNames:Record<OpStatus,string>={pending:'Na čakanju',in_progress:'V izdelavi',done:'Zaključeno'};
const priorityNames:Record<Priority,string>={low:'Nizka',medium:'Srednja',high:'Visoka'};
const toolNames:Record<ToolCondition,string>={available:'Na voljo',maintenance:'V vzdrževanju',unavailable:'Ni na voljo'};
const reservationNames:Record<ReservationStatus,string>={reserved:'Rezervirano',in_use:'V uporabi',released:'Sproščeno'};
const machineCategories:Record<MachineCategory,string>={cnc_lathe:'CNC stružnica',cnc_mill:'CNC rezkalni stroj',manual_lathe:'Klasična stružnica',manual_mill:'Klasični rezkalni stroj',grinder:'Brusilni stroj',saw:'Žaga',drill:'Vrtalni stroj',other:'Drugo'};
const eur=(value:number)=>new Intl.NumberFormat('sl-SI',{style:'currency',currency:'EUR'}).format(value);
const estimatedOpMinutes=(o:Operation,qty:number)=>o.setupMinutes||o.cycleMinutes ? (o.setupMinutes||0)+(o.cycleMinutes||0)*qty : o.estimatedMinutes;
const actualOpMinutes=(o:Operation)=>operationMinutes(o);
const operationRate=(o:Operation,machines:Machine[])=>o.hourlyRateOverride ?? machines.find(m=>m.id===o.machineId)?.hourlyRate ?? 0;
const opCost=(o:Operation,qty:number,machines:Machine[],actual=false)=>((actual?actualOpMinutes(o):estimatedOpMinutes(o,qty))/60)*operationRate(o,machines)+(o.extraCost||0);
const orderCost=(w:WorkOrder,machines:Machine[],actual=false)=>w.operations.reduce((sum,o)=>sum+opCost(o,w.quantity,machines,actual),0);
const processes=['Struženje','Rezkanje','Vrtanje','Brušenje','Rezanje navojev','Žaganje','Varjenje','Drugo'];
const categories=['Stružni noži','Rezkarji','Svedri','Navojna orodja','Brusilna orodja','Merilna orodja','Vpenjalna orodja','Drugo'];
const progress=(w:WorkOrder)=>w.operations.length?Math.round(w.operations.filter(o=>o.status==='done').length/w.operations.length*100):0;
const operationMinutes=(o:Operation)=>o.manualMinutes+(o.timeRecords||[]).reduce((a,r)=>a+r.minutes,0);
const duration=(n:number)=>`${Math.floor(n/60)} h ${Math.round(n%60)} min`;
const tone=(v:string)=>v==='available'||v==='done'?'bg-[#16372d] text-[#85e7bd]':v==='in_progress'||v==='in_use'?'bg-[#422f1d] text-[#ffd39a]':v==='reserved'?'bg-[#142747] text-[#91baff]':v==='maintenance'||v==='unavailable'?'bg-[#40202b] text-[#ffb4ba]':'bg-[#222e3e] text-[#bbc9db]';
const icon:Record<Page,string>={dashboard:'▦',orders:'▤',materials:'▧',tools:'⚒',machines:'⚙',archive:'◷',schedules:'▦',quotes:'€',products:'▣',inspections:'✓',employees:'♟',drawings:'▤'};
const nav:Record<Page,string>={dashboard:'Pregled',orders:'Delovni nalogi',materials:'Materiali',tools:'Orodja',machines:'Stroji',archive:'Arhiv',schedules:'Plan',quotes:'Ponudbe',products:'Izdelki',inspections:'Kakovost',employees:'Delavci',drawings:'Risbe'};
const newOrder=():Partial<WorkOrder>=>({product:'',customer:'',description:'',quantity:1,startDate:today(),deadline:'',priority:'medium',status:'planned',notes:'',operations:[],materialAssignments:[]});
const newMaterial=():Partial<Material>=>({name:'',standard:'',shape:'Okrogla palica',dimensions:'',quantity:0,unit:'kos',location:''});
const newMachine=():Partial<Machine>=>({name:'',category:'cnc_lathe',code:'',manufacturer:'',hourlyRate:50,condition:'available',notes:''});
const newTool=():Partial<Tool>=>({name:'',category:categories[0],manufacturer:'',specification:'',size:'',location:'',condition:'available',notes:''});
async function request<T>(url:string,method='GET',data?:unknown):Promise<T>{const response=await fetch(API+url,{method,headers:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data)});let result:unknown;try{result=await response.json()}catch{throw Error('Neveljaven odgovor strežnika.')}if(!response.ok)throw Error((result as {error?:string}).error||'Napaka pri shranjevanju.');return result as T;}
function Tag({value,label}:{value:string;label:string}){return <span className={'tag '+tone(value)}><span className="h-1.5 w-1.5 rounded-full bg-current"/>{label}</span>}
function Field({label,children}:{label:string;children:ReactNode}){return <label className="field">{label}{children}</label>}
function Empty({icon:ico,title,desc,action}:{icon:string;title:string;desc:string;action?:ReactNode}){return <div className="card flex flex-col items-center justify-center px-5 py-14 text-center"><div className="mb-4 rounded-2xl bg-[#222e3e] px-5 py-3 text-3xl">{ico}</div><h3 className="font-bold text-[#eef3fd]">{title}</h3><p className="mt-2 mb-5 max-w-xs text-sm text-[#92a4bd]">{desc}</p>{action}</div>}
function Modal({title,onClose,children}:{title:string;onClose:()=>void;children:ReactNode}){return <div className="modal-backdrop fixed inset-0 z-50 flex items-center justify-center bg-[#0e1b32]/55 p-2 sm:p-4" onMouseDown={onClose}><div className="modal-panel w-full max-w-xl max-h-[92dvh] overflow-y-auto rounded-2xl bg-[#141d29] p-4 shadow-2xl sm:rounded-3xl sm:p-7" onMouseDown={e=>e.stopPropagation()}><div className="mb-5 flex items-center justify-between"><h2 className="text-xl font-extrabold">{title}</h2><button className="btn ghost" onClick={onClose} aria-label="Zapri">✕</button></div>{children}</div></div>}
function OrderForm({original,onSave,onClose,busy}:{original?:WorkOrder;onSave:(value:Partial<WorkOrder>)=>void;onClose:()=>void;busy:boolean}){
 const [form,setForm]=useState<Partial<WorkOrder>>(original||newOrder()); const set=<K extends keyof WorkOrder>(key:K,value:WorkOrder[K])=>setForm(f=>({...f,[key]:value}));
 return <Modal title={original?'Uredi delovni nalog':'Nov delovni nalog'} onClose={onClose}><form className="space-y-4" onSubmit={e=>{e.preventDefault();onSave(form)}}><div className="grid gap-4 sm:grid-cols-2"><Field label="Ime izdelka *"><input className="control" required value={form.product||''} onChange={e=>set('product',e.target.value)}/></Field><Field label="Naročnik *"><input className="control" required value={form.customer||''} onChange={e=>set('customer',e.target.value)}/></Field></div><Field label="Opis"><textarea className="control min-h-20" value={form.description||''} onChange={e=>set('description',e.target.value)}/></Field><div className="grid grid-cols-1 gap-4 min-[420px]:grid-cols-2"><Field label="Količina *"><input className="control" type="number" min="1" step="1" required value={form.quantity??1} onChange={e=>set('quantity',Number(e.target.value))}/></Field><Field label="Prioriteta"><select className="control" value={form.priority} onChange={e=>set('priority',e.target.value as Priority)}>{Object.entries(priorityNames).map(([v,l])=><option value={v} key={v}>{l}</option>)}</select></Field><Field label="Datum začetka"><input className="control" type="date" required value={form.startDate||today()} onChange={e=>set('startDate',e.target.value)}/></Field><Field label="Rok izdelave"><input className="control" type="date" value={form.deadline||''} onChange={e=>set('deadline',e.target.value)}/></Field></div><Field label="Stanje"><select className="control" value={form.status} onChange={e=>set('status',e.target.value as OrderStatus)}>{Object.entries(statusNames).map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></Field><div className="flex justify-end gap-2 pt-2"><button type="button" className="btn ghost" onClick={onClose}>Prekliči</button><button className="btn primary" disabled={busy}>✓ Shrani nalog</button></div></form></Modal>
}
function MaterialForm({original,onSave,onClose,busy}:{original?:Material;onSave:(value:Partial<Material>)=>void;onClose:()=>void;busy:boolean}){
 const [f,setF]=useState<Partial<Material>>(original||newMaterial()); const set=<K extends keyof Material>(k:K,v:Material[K])=>setF(x=>({...x,[k]:v}));
 return <Modal title={original?'Uredi material':'Dodaj material'} onClose={onClose}><form className="space-y-4" onSubmit={e=>{e.preventDefault();onSave(f)}}><div className="grid grid-cols-1 gap-4 min-[420px]:grid-cols-2"><Field label="Naziv materiala *"><input className="control" required value={f.name||''} onChange={e=>set('name',e.target.value)}/></Field><Field label="Standard / oznaka"><input className="control" placeholder="npr. C45" value={f.standard||''} onChange={e=>set('standard',e.target.value)}/></Field><Field label="Oblika"><select className="control" value={f.shape} onChange={e=>set('shape',e.target.value)}>{['Okrogla palica','Kvadratna palica','Pločevina','Cev','Drugo'].map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Dimenzije"><input className="control" placeholder="Ø 30 × 500 mm" value={f.dimensions||''} onChange={e=>set('dimensions',e.target.value)}/></Field><Field label="Količina na zalogi"><input className="control" required type="number" min="0" step="any" value={f.quantity??0} onChange={e=>set('quantity',Number(e.target.value))}/></Field><Field label="Enota"><select className="control" value={f.unit} onChange={e=>set('unit',e.target.value as Material['unit'])}>{['kos','mm','m','kg'].map(x=><option key={x}>{x}</option>)}</select></Field></div><Field label="Lokacija skladiščenja"><input className="control" value={f.location||''} onChange={e=>set('location',e.target.value)}/></Field><div className="flex justify-end gap-2"><button type="button" className="btn ghost" onClick={onClose}>Prekliči</button><button disabled={busy} className="btn primary">✓ Shrani material</button></div></form></Modal>
}
function ToolForm({original,onSave,onClose,busy}:{original?:Tool;onSave:(value:Partial<Tool>)=>void;onClose:()=>void;busy:boolean}){
 const [f,setF]=useState<Partial<Tool>>(original||newTool());const set=<K extends keyof Tool>(k:K,v:Tool[K])=>setF(x=>({...x,[k]:v}));
 return <Modal title={original?'Uredi orodje':'Dodaj orodje'} onClose={onClose}><form className="space-y-4" onSubmit={e=>{e.preventDefault();onSave(f)}}><Field label="Ime orodja *"><input required className="control" value={f.name||''} onChange={e=>set('name',e.target.value)}/></Field><div className="grid grid-cols-1 gap-4 min-[420px]:grid-cols-2"><Field label="Kategorija"><select className="control" value={f.category} onChange={e=>set('category',e.target.value)}>{categories.map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Proizvajalec"><input className="control" value={f.manufacturer||''} onChange={e=>set('manufacturer',e.target.value)}/></Field><Field label="Oznaka"><input className="control" value={f.specification||''} onChange={e=>set('specification',e.target.value)}/></Field><Field label="Velikost / premer"><input className="control" placeholder="Ø 10 mm" value={f.size||''} onChange={e=>set('size',e.target.value)}/></Field><Field label="Lokacija"><input className="control" value={f.location||''} onChange={e=>set('location',e.target.value)}/></Field><Field label="Stanje"><select className="control" value={f.condition} onChange={e=>set('condition',e.target.value as ToolCondition)}>{Object.entries(toolNames).map(([v,l])=><option value={v} key={v}>{l}</option>)}</select></Field></div><Field label="Opombe"><textarea className="control" value={f.notes||''} onChange={e=>set('notes',e.target.value)}/></Field><div className="flex justify-end gap-2"><button type="button" className="btn ghost" onClick={onClose}>Prekliči</button><button disabled={busy} className="btn primary">✓ Shrani orodje</button></div></form></Modal>
}
function MachineForm({original,onSave,onClose,busy}:{original?:Machine;onSave:(value:Partial<Machine>)=>void;onClose:()=>void;busy:boolean}){
 const [f,setF]=useState<Partial<Machine>>(original||newMachine());const set=<K extends keyof Machine>(k:K,v:Machine[K])=>setF(x=>({...x,[k]:v}));
 return <Modal title={original?'Uredi stroj':'Dodaj stroj'} onClose={onClose}><form className="space-y-4" onSubmit={e=>{e.preventDefault();onSave(f)}}><Field label="Ime stroja *"><input required className="control" value={f.name||''} onChange={e=>set('name',e.target.value)}/></Field><div className="grid grid-cols-1 gap-4 min-[420px]:grid-cols-2"><Field label="Vrsta stroja"><select className="control" value={f.category} onChange={e=>set('category',e.target.value as MachineCategory)}>{Object.entries(machineCategories).map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></Field><Field label="Oznaka stroja"><input className="control" placeholder="CNC-01" value={f.code||''} onChange={e=>set('code',e.target.value)}/></Field><Field label="Proizvajalec"><input className="control" value={f.manufacturer||''} onChange={e=>set('manufacturer',e.target.value)}/></Field><Field label="Cena ure obdelave (€/h)"><input className="control" type="number" min="0" step="0.01" required value={f.hourlyRate??0} onChange={e=>set('hourlyRate',Number(e.target.value))}/></Field><Field label="Stanje"><select className="control" value={f.condition} onChange={e=>set('condition',e.target.value as ToolCondition)}>{Object.entries(toolNames).map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></Field></div><Field label="Opombe"><textarea className="control" value={f.notes||''} onChange={e=>set('notes',e.target.value)}/></Field><div className="flex justify-end gap-2"><button type="button" className="btn ghost" onClick={onClose}>Prekliči</button><button disabled={busy} className="btn primary">Shrani stroj</button></div></form></Modal>
}
function OperationEditForm({op,machines,onSave,onClose,busy}:{op:Operation;machines:Machine[];onSave:(patch:Partial<Operation>)=>void;onClose:()=>void;busy:boolean}){
 const [f,setF]=useState(op);const set=<K extends keyof Operation>(key:K,value:Operation[K])=>setF(prev=>({...prev,[key]:value}));
 return <Modal title="Uredi obdelavo in kalkulacijo" onClose={onClose}><form className="space-y-4" onSubmit={e=>{e.preventDefault();onSave({name:f.name,description:f.description,machineId:f.machineId||null,estimatedMinutes:f.estimatedMinutes,setupMinutes:f.setupMinutes||0,cycleMinutes:f.cycleMinutes||0,hourlyRateOverride:f.hourlyRateOverride??null,extraCost:f.extraCost||0,manualMinutes:f.manualMinutes})}}><Field label="Naziv obdelave"><input className="control" required value={f.name} onChange={e=>set('name',e.target.value)}/></Field><Field label="Stroj"><select className="control" value={f.machineId||''} onChange={e=>set('machineId',e.target.value||null)}><option value="">Brez dodeljenega stroja</option>{machines.map(m=><option key={m.id} value={m.id}>{m.name} · {machineCategories[m.category]} · {eur(m.hourlyRate)}/h</option>)}</select></Field><div className="grid grid-cols-1 gap-4 min-[420px]:grid-cols-2"><Field label="Priprava (min)"><input className="control" type="number" min="0" step="0.1" value={f.setupMinutes??0} onChange={e=>set('setupMinutes',Number(e.target.value))}/></Field><Field label="Obdelava na kos (min)"><input className="control" type="number" min="0" step="0.1" value={f.cycleMinutes??0} onChange={e=>set('cycleMinutes',Number(e.target.value))}/></Field><Field label="Osnovna ocena (min)"><input className="control" type="number" min="0" step="0.1" value={f.estimatedMinutes} onChange={e=>set('estimatedMinutes',Number(e.target.value))}/></Field><Field label="Dejanski čas - ročno (min)"><input className="control" type="number" min="0" step="0.1" value={f.manualMinutes} onChange={e=>set('manualMinutes',Number(e.target.value))}/></Field><Field label="Lastna urna postavka (€/h)"><input className="control" type="number" min="0" step="0.01" placeholder="Privzeta cena stroja" value={f.hourlyRateOverride??''} onChange={e=>set('hourlyRateOverride',e.target.value===''?null:Number(e.target.value))}/></Field><Field label="Dodatni strošek (€)"><input className="control" type="number" min="0" step="0.01" value={f.extraCost??0} onChange={e=>set('extraCost',Number(e.target.value))}/></Field></div><Field label="Opis operacije"><textarea className="control" value={f.description} onChange={e=>set('description',e.target.value)}/></Field><p className="text-xs text-[#a4b2c6]">Če sta priprava in čas na kos nič, se uporabi osnovna ocena. Lastna urna postavka preglasi postavko stroja.</p><div className="flex justify-end gap-2"><button type="button" className="btn ghost" onClick={onClose}>Prekliči</button><button disabled={busy} className="btn primary">Shrani kalkulacijo</button></div></form></Modal>
}
function OperationForm({onSave,onClose}:{onSave:(op:Operation)=>void;onClose:()=>void}){
 const [name,setName]=useState('Struženje'),[custom,setCustom]=useState(''),[description,setDescription]=useState(''),[estimate,setEstimate]=useState(30);
 return <Modal title="Dodaj operacijo" onClose={onClose}><form className="space-y-4" onSubmit={e=>{e.preventDefault();onSave({id:'',name:name==='Drugo'?custom:name,description,estimatedMinutes:estimate,manualMinutes:0,status:'pending',sequence:0,startedAt:null,timeRecords:[]})}}><Field label="Postopek obdelave"><select className="control" value={name} onChange={e=>setName(e.target.value)}>{processes.map(x=><option key={x}>{x}</option>)}</select></Field>{name==='Drugo'&&<Field label="Ime postopka"><input required className="control" value={custom} onChange={e=>setCustom(e.target.value)}/></Field>}<Field label="Opis postopka"><textarea className="control" value={description} onChange={e=>setDescription(e.target.value)}/></Field><Field label="Predvideni čas (min)"><input className="control" type="number" min="0" value={estimate} onChange={e=>setEstimate(Number(e.target.value))}/></Field><div className="flex justify-end gap-2"><button type="button" className="btn ghost" onClick={onClose}>Prekliči</button><button className="btn primary">Dodaj operacijo</button></div></form></Modal>
}
function WorkCard({w,onClick}:{w:WorkOrder;onClick:()=>void}){return <button onClick={onClick} className="card w-full p-5 text-left transition hover:border-[#365b95] hover:shadow-md"><div className="flex items-start justify-between gap-3"><div className="flex items-start gap-3"><div className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl bg-[#142747] text-xl text-[#71a6ff]">▤</div><div><div className="text-xs font-bold text-[#71a6ff]">{w.number}</div><div className="mt-0.5 font-extrabold text-[#eef3fd]">{w.product}</div><div className="mt-1 text-xs text-[#92a4bd]">{w.customer}</div></div></div><Tag value={w.status} label={statusNames[w.status]}/></div><div className="mt-5 flex items-center justify-between text-xs text-[#92a4bd]"><span>Rok: {fmtDate(w.deadline)}</span><span className="font-bold text-[#d8e2f2]">{progress(w)} %</span></div><div className="progress mt-2"><div style={{width:`${progress(w)}%`}}/></div></button>}
export default function App(){
 const [page,setPage]=useState<Page>('dashboard'),[orders,setOrders]=useState<WorkOrder[]>([]),[materials,setMaterials]=useState<Material[]>([]),[tools,setTools]=useState<Tool[]>([]),[machines,setMachines]=useState<Machine[]>([]),[reservations,setReservations]=useState<Reservation[]>([]),[selected,setSelected]=useState<string|null>(null),[loading,setLoading]=useState(true),[busy,setBusy]=useState(false),[error,setError]=useState(''),[message,setMessage]=useState(''),[modal,setModal]=useState<'order'|'material'|'tool'|'machine'|'operation'|'editOperation'|null>(null),[editing,setEditing]=useState<string|null>(null),[editingOperation,setEditingOperation]=useState<string|null>(null),[search,setSearch]=useState(''),[filter,setFilter]=useState('all'),[noteDraft,setNoteDraft]=useState(''),[showAssign,setShowAssign]=useState(false),[materialId,setMaterialId]=useState(''),[materialQty,setMaterialQty]=useState(1),[toolId,setToolId]=useState(''),[toolOpId,setToolOpId]=useState('');
 const selectedOrder=orders.find(w=>w.id===selected)||null;
 const [mobileMenuOpen,setMobileMenuOpen]=useState(false);
 const editingOrder=orders.find(w=>w.id===editing);const editingMaterial=materials.find(m=>m.id===editing);const editingTool=tools.find(t=>t.id===editing);const editingMachine=machines.find(m=>m.id===editing);const currentOp=selectedOrder?.operations.find(o=>o.id===editingOperation);
 const activeReservations=reservations.filter(r=>r.status!=='released');
 const getReservation=(t:string)=>activeReservations.find(r=>r.toolId===t);
 const toolStatus=(t:Tool):ToolCondition|ReservationStatus=>t.condition!=='available'?t.condition:(getReservation(t.id)?.status||'available');
 const refresh=async()=>{try{const [o,m,t,r,ms]=await Promise.all([request<WorkOrder[]>('/work-orders'),request<Material[]>('/materials'),request<Tool[]>('/tools'),request<Reservation[]>('/tool-reservations'),request<Machine[]>('/machines')]);setOrders(o);setMaterials(m);setTools(t);setReservations(r);setMachines(ms);setError('')}catch(e){setError(e instanceof TypeError?'Povezava s strežnikom ni uspela.':e instanceof Error?e.message:'Napaka pri nalaganju.')}finally{setLoading(false)}};
 useEffect(()=>{void refresh()},[]);
 useEffect(()=>{if(selectedOrder)setNoteDraft(selectedOrder.notes)},[selectedOrder?.id]);
 const mutate=async(fn:()=>Promise<unknown>,ok='Spremembe so shranjene.')=>{setBusy(true);setError('');try{await fn();await refresh();setMessage(ok);window.setTimeout(()=>setMessage(''),3500);return true}catch(e){setError(e instanceof TypeError?'Povezava s strežnikom ni uspela.':e instanceof Error?e.message:'Prišlo je do napake.');return false}finally{setBusy(false)}};
 const saveOrder=async(value:Partial<WorkOrder>)=>{const ok=await mutate(()=>request(`/work-orders${editing?'/'+editing:''}`,editing?'PUT':'POST',value),'Delovni nalog je shranjen.');if(ok){setModal(null);setEditing(null)}};
 const saveMaterial=async(value:Partial<Material>)=>{const ok=await mutate(()=>request(`/materials${editing?'/'+editing:''}`,editing?'PUT':'POST',value),'Material je shranjen.');if(ok){setModal(null);setEditing(null)}};
 const saveTool=async(value:Partial<Tool>)=>{const ok=await mutate(()=>request(`/tools${editing?'/'+editing:''}`,editing?'PUT':'POST',value),'Orodje je shranjeno.');if(ok){setModal(null);setEditing(null)}};
 const saveMachine=async(value:Partial<Machine>)=>{const ok=await mutate(()=>request(`/machines${editing?'/'+editing:''}`,editing?'PUT':'POST',value),'Stroj je shranjen.');if(ok){setModal(null);setEditing(null)}};
 const patchOrder=(patch:Partial<WorkOrder>):Promise<boolean>=>selectedOrder?mutate(()=>request(`/work-orders/${selectedOrder.id}`,'PUT',{...selectedOrder,...patch})):Promise.resolve(false);
 const deleteItem=async(type:'work-orders'|'materials'|'tools'|'machines',itemId:string)=>{if(!window.confirm(type==='work-orders'?'Ali res želiš izbrisati delovni nalog?':'Ali res želiš izbrisati zapis?'))return;const ok=await mutate(()=>request(`/${type}/${itemId}`,'DELETE'),'Zapis je izbrisan.');if(ok&&type==='work-orders')setSelected(null)};
 const addOperation=async(op:Operation)=>{if(!selectedOrder)return;const ok=await mutate(()=>request(`/work-orders/${selectedOrder.id}`,'PUT',{...selectedOrder,operations:[...selectedOrder.operations,op]}),'Operacija je dodana.');if(ok)setModal(null)};
 const updateOp=(opId:string,patch:Partial<Operation>)=>{if(!selectedOrder)return;return patchOrder({operations:selectedOrder.operations.map(o=>o.id===opId?{...o,...patch}:o)})};
 const removeOp=(opId:string)=>{if(!selectedOrder||!window.confirm('Ali želiš izbrisati operacijo?'))return;return patchOrder({operations:selectedOrder.operations.filter(o=>o.id!==opId)})};
 const moveOp=(index:number,direction:number)=>{if(!selectedOrder)return;const ops=[...selectedOrder.operations];const target=index+direction;if(target<0||target>=ops.length)return;[ops[index],ops[target]]=[ops[target],ops[index]];return patchOrder({operations:ops})};
 const filteredOrders=orders.filter(w=>(page==='archive'?w.status==='done':page==='orders'?w.status!=='done':true)&&`${w.number} ${w.customer} ${w.product}`.toLowerCase().includes(search.toLowerCase())&&(filter==='all'||w.status===filter));
 const filteredTools=tools.filter(t=>`${t.name} ${t.category} ${t.manufacturer} ${t.size}`.toLowerCase().includes(search.toLowerCase())&&(filter==='all'||toolStatus(t)===filter));
 const machineUsage=(machineId:string)=>orders.find(w=>w.operations.some(o=>o.machineId===machineId&&o.status==='in_progress'));
 const machineStatus=(m:Machine)=>m.condition!=='available'?m.condition:machineUsage(m.id)?'in_use':'available';
 const filteredMachines=machines.filter(m=>`${m.name} ${m.code} ${m.manufacturer} ${machineCategories[m.category]}`.toLowerCase().includes(search.toLowerCase())&&(filter==='all'||machineStatus(m)===filter));
 const filteredMaterials=materials.filter(m=>`${m.name} ${m.standard} ${m.dimensions}`.toLowerCase().includes(search.toLowerCase()));
 const changePage=(p:Page)=>{setMobileMenuOpen(false);setPage(p);setSelected(null);setSearch('');setFilter('all');setError('');setShowAssign(false)};
 const title=selectedOrder?selectedOrder.number:nav[page];
 const reserve=async()=>{if(!selectedOrder||!toolId||!toolOpId)return;const ok=await mutate(()=>request('/tool-reservations','POST',{toolId,workOrderId:selectedOrder.id,operationId:toolOpId}),'Orodje je rezervirano.');if(ok){setToolId('');setShowAssign(false)}};
 return <div className="app-shell min-h-screen md:flex"><aside className="sticky top-0 hidden h-screen min-h-0 w-[250px] shrink-0 overflow-y-auto border-r border-[#293448] bg-[#141d29] px-5 py-7 md:flex md:flex-col"><div className="flex items-center gap-3 px-3"><div className="flex h-11 w-11 items-center justify-center rounded-xl bg-blue-600 text-2xl font-bold text-white">⚙</div><div><div className="font-extrabold tracking-tight">Delovni nalogi</div><div className="text-[11px] font-medium text-[#92a4bd]">UPRAVLJANJE DELAVNICE</div></div></div><p className="mb-3 mt-12 px-4 text-[11px] font-extrabold tracking-widest text-[#8394ad]">MENI</p><nav className="space-y-1">{(Object.keys(nav) as Page[]).map(p=><button key={p} className={'sidebar-link '+(page===p?'active':'')} onClick={()=>changePage(p)}><span className="w-5 text-center text-lg">{icon[p]}</span>{nav[p]}</button>)}</nav><div className="mt-auto rounded-2xl bg-[#142747] p-4"><div className="mb-1 text-sm font-bold text-[#eef3fd]">🔧 Delavnica na dlani</div><div className="text-xs leading-5 text-[#a4b2c6]">Vsi nalogi, materiali in orodja na enem mestu.</div></div><div className="mt-4 px-3 text-[11px] text-[#92a4bd]">Delovni nalogi · PRO 3.1 · DARK</div></aside>
 <div className="app-workspace min-w-0 flex-1"><header className="app-header sticky top-0 z-20 flex min-h-[68px] items-center justify-between gap-2 border-b border-[#293448] bg-[#0d131d]/95 px-4 py-3 backdrop-blur sm:px-6 md:min-h-[76px] md:px-10"><div className="flex items-center gap-3"><div className="flex h-9 w-9 items-center justify-center rounded-lg bg-blue-600 text-xl text-white md:hidden">⚙</div><div><h1 className="text-lg font-extrabold tracking-tight md:text-xl">{title}</h1><div className="text-xs text-[#92a4bd]">{selectedOrder?'Podrobnosti delovnega naloga':page==='dashboard'?'Dobrodošli v vaši delavnici':'Upravljanje delavnice'}</div></div></div><div className="flex items-center gap-3"><span className="hidden text-xs font-medium text-[#92a4bd] sm:block">{new Date().toLocaleDateString('sl-SI',{day:'numeric',month:'long',year:'numeric'})}</span><span className="flex h-9 w-9 items-center justify-center rounded-full border border-[#29436a] bg-[#142747] text-[#91baff]">👤</span></div></header>
 <main className="content-pad app-main mx-auto w-full max-w-[1200px] min-w-0 space-y-5 px-3 py-5 sm:px-6 md:space-y-6 md:px-10 md:py-9">{error&&<div role="alert" className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-[#763845] bg-[#40202b] p-4 text-sm text-[#ffb4ba]"><span>⚠ {error}</span><button className="btn danger" onClick={()=>{setError('');void refresh()}}>Poskusi znova</button></div>}{message&&<div role="status" className="rounded-xl border border-[#38634e] bg-[#16372d] p-3 text-sm text-[#85e7bd]">✓ {message}</div>}
 {loading?<div className="card p-10 text-center text-[#a4b2c6]">Nalaganje ...</div>:selectedOrder?<>
  <button className="btn ghost -ml-3" onClick={()=>setSelected(null)}>← Nazaj na naloge</button><div className="card p-5 md:p-7"><div className="flex flex-wrap items-start justify-between gap-4"><div><span className="text-xs font-bold text-[#71a6ff]">{selectedOrder.number}</span><h2 className="mt-1 text-2xl font-extrabold tracking-tight">{selectedOrder.product}</h2><p className="mt-1 text-sm text-[#92a4bd]">{selectedOrder.customer} · {selectedOrder.quantity} kos · rok {fmtDate(selectedOrder.deadline)}</p></div><div className="flex flex-wrap items-center gap-2"><Tag value={selectedOrder.status} label={statusNames[selectedOrder.status]}/><button className="btn secondary" onClick={()=>{setEditing(selectedOrder.id);setModal('order')}}>✎ Uredi</button><button className="btn danger" disabled={busy} onClick={()=>void deleteItem('work-orders',selectedOrder.id)}>Izbriši</button></div></div><div className="mt-7 grid gap-5 sm:grid-cols-3"><div className="rounded-xl bg-[#192330] p-4"><p className="text-xs text-[#92a4bd]">Napredek izdelave</p><p className="mt-1 text-2xl font-extrabold">{progress(selectedOrder)} %</p><div className="progress mt-3"><div style={{width:`${progress(selectedOrder)}%`}}/></div></div><div className="rounded-xl bg-[#192330] p-4"><p className="text-xs text-[#92a4bd]">Skupni čas izdelave</p><p className="mt-1 text-2xl font-extrabold">{duration(selectedOrder.operations.reduce((sum,o)=>sum+operationMinutes(o),0))}</p></div><div className="rounded-xl bg-[#192330] p-4"><p className="text-xs text-[#92a4bd]">Operacije</p><p className="mt-1 text-2xl font-extrabold">{selectedOrder.operations.filter(o=>o.status==='done').length} <span className="text-[#92a4bd]">/ {selectedOrder.operations.length}</span></p></div></div></div>
  <section className="card p-5 md:p-7"><h3 className="section-title mb-4">€ Kalkulacija proizvodnje</h3><div className="grid gap-3 sm:grid-cols-3"><div className="rounded-xl bg-[#142747] p-4"><p className="text-xs text-[#91baff]">Predvidena cena obdelav</p><p className="mt-2 text-2xl font-extrabold text-[#c7ddff]">{eur(orderCost(selectedOrder,machines))}</p></div><div className="rounded-xl bg-[#192330] p-4"><p className="text-xs text-[#a4b2c6]">Dejanski obračun obdelav</p><p className="mt-2 text-2xl font-extrabold">{eur(orderCost(selectedOrder,machines,true))}</p></div><div className="rounded-xl bg-[#192330] p-4"><p className="text-xs text-[#a4b2c6]">Predvideni čas obdelav</p><p className="mt-2 text-2xl font-extrabold">{duration(selectedOrder.operations.reduce((s,o)=>s+estimatedOpMinutes(o,selectedOrder.quantity),0))}</p></div></div><p className="mt-3 text-xs text-[#a4b2c6]">Cena = (čas / 60) × urna postavka + dodatni strošek. Priprava se obračuna enkrat, čas na kos za celotno količino. Cena materiala in DDV nista vključena.</p></section>
  <section className="card p-5 md:p-7"><div className="mb-5 flex flex-wrap items-center justify-between gap-3"><h3 className="section-title">⚙ Postopki obdelave</h3><button className="btn secondary" onClick={()=>setModal('operation')}>＋ Dodaj operacijo</button></div>{selectedOrder.operations.length===0?<p className="py-6 text-center text-sm text-[#92a4bd]">Ni dodanih operacij.</p>:<div className="space-y-3">{selectedOrder.operations.map((o,i)=><div key={o.id} className="rounded-xl border border-[#293448] bg-[#111a26]/50 p-4"><div className="flex flex-wrap items-start justify-between gap-3"><div className="flex min-w-0 gap-3"><div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg bg-[#142747] font-extrabold text-[#71a6ff]">{i+1}</div><div><p className="font-bold">{o.name}</p><p className="text-xs text-[#92a4bd]">{o.description||'Brez opisa'} · Stroj: {machines.find(m=>m.id===o.machineId)?.name||'Ni dodeljen'}</p></div></div><Tag value={o.status} label={opNames[o.status]}/></div><div className="mt-3 grid gap-2 rounded-xl bg-[#141d29] p-3 text-sm sm:grid-cols-3"><div><span className="text-xs text-[#a4b2c6]">Planirani čas</span><p className="font-bold">{duration(estimatedOpMinutes(o,selectedOrder.quantity))}</p></div><div><span className="text-xs text-[#a4b2c6]">Predvidena cena</span><p className="font-bold text-[#91baff]">{eur(opCost(o,selectedOrder.quantity,machines))}</p></div><div><span className="text-xs text-[#a4b2c6]">Dejanski obračun</span><p className="font-bold">{eur(opCost(o,selectedOrder.quantity,machines,true))}</p></div></div><div className="mt-3 flex flex-wrap items-center gap-2"><button className="btn secondary !min-h-9" disabled={busy} onClick={()=>{setEditingOperation(o.id);setModal('editOperation')}}>✎ Kalkulacija</button><select className="control !w-auto !min-h-9 !py-1 text-xs" value={o.status} disabled={busy} onChange={e=>void updateOp(o.id,{status:e.target.value as OpStatus})}>{Object.entries(opNames).map(([v,l])=><option key={v} value={v}>{l}</option>)}</select>{o.startedAt?<button disabled={busy} className="btn secondary !min-h-9" onClick={()=>void mutate(()=>request(`/work-orders/${selectedOrder.id}/operations/${o.id}/stop`,'POST',{}),'Merjenje časa je ustavljeno.')}>■ Ustavi</button>:<button disabled={busy||o.status==='done'} className="btn secondary !min-h-9" onClick={()=>void mutate(()=>request(`/work-orders/${selectedOrder.id}/operations/${o.id}/start`,'POST',{}),'Merjenje časa se je začelo.')}>▶ Začni delo</button>}<span className="text-xs text-[#a4b2c6]">Porabljeno: {duration(operationMinutes(o))}{o.startedAt?' · čas teče':''}</span><div className="ml-auto flex gap-1"><button title="Premakni gor" disabled={busy||i===0} className="btn ghost !min-h-9 !px-2" onClick={()=>void moveOp(i,-1)}>↑</button><button title="Premakni dol" disabled={busy||i===selectedOrder.operations.length-1} className="btn ghost !min-h-9 !px-2" onClick={()=>void moveOp(i,1)}>↓</button><button title="Izbriši operacijo" disabled={busy} className="btn danger !min-h-9 !px-2" onClick={()=>void removeOp(o.id)}>✕</button></div></div></div>)}</div>}</section>
  <section className="card p-5 md:p-7"><div className="mb-5 flex flex-wrap items-center justify-between gap-2"><h3 className="section-title">▧ Material</h3><button className="btn secondary" onClick={()=>setShowAssign(x=>!x)}>＋ Dodeli material / orodje</button></div>{showAssign&&<div className="mb-5 grid gap-4 rounded-xl bg-[#142747] p-4 sm:grid-cols-2"><div className="space-y-3"><div className="text-sm font-bold">Dodaj material</div><select className="control" value={materialId} onChange={e=>setMaterialId(e.target.value)}><option value="">Izberi material ...</option>{materials.map(m=><option key={m.id} value={m.id}>{m.name} · zaloga {m.quantity} {m.unit}</option>)}</select><input type="number" min="0.000001" step="any" className="control" value={materialQty} onChange={e=>setMaterialQty(Number(e.target.value))}/><button className="btn primary w-full" disabled={busy||!materialId||materialQty<=0} onClick={()=>{void patchOrder({materialAssignments:[...selectedOrder.materialAssignments,{id:'',materialId,quantity:materialQty,consumed:false}]}).then(ok=>{if(ok){setMaterialId('');setMaterialQty(1)}})}}>Dodeli material</button></div><div className="space-y-3"><div className="text-sm font-bold">Rezerviraj orodje</div><select className="control" value={toolOpId} onChange={e=>setToolOpId(e.target.value)}><option value="">Izberi operacijo ...</option>{selectedOrder.operations.map(o=><option key={o.id} value={o.id}>{o.name}</option>)}</select><select className="control" value={toolId} onChange={e=>setToolId(e.target.value)}><option value="">Izberi razpoložljivo orodje ...</option>{tools.filter(t=>toolStatus(t)==='available').map(t=><option key={t.id} value={t.id}>{t.name} {t.size}</option>)}</select><button className="btn primary w-full" disabled={busy||!toolId||!toolOpId} onClick={()=>void reserve()}>Rezerviraj orodje</button></div></div>}{selectedOrder.materialAssignments.length===0?<p className="text-sm text-[#92a4bd]">Ni dodeljenega materiala.</p>:<div className="space-y-3">{selectedOrder.materialAssignments.map(a=>{const mat=materials.find(m=>m.id===a.materialId);return <div key={a.id} className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-[#293448] p-3"><div><p className="font-bold">{mat?.name||'Izbrisan material'}</p><p className="text-xs text-[#92a4bd]">Potrebno: {a.quantity} {mat?.unit} · zaloga: {mat?.quantity??0} {mat?.unit}</p></div>{a.consumed?<Tag value="done" label="Poraba potrjena"/>:<div className="flex gap-2"><button className="btn secondary" disabled={busy||!mat||mat.quantity<a.quantity} onClick={()=>void mutate(()=>request(`/work-orders/${selectedOrder.id}/material-consumption`,'POST',{assignmentId:a.id}),'Poraba materiala je potrjena.')}>Potrdi porabo</button><button className="btn danger !px-3" disabled={busy} onClick={()=>void patchOrder({materialAssignments:selectedOrder.materialAssignments.filter(x=>x.id!==a.id)})}>✕</button></div>}</div>})}</div>}<h4 className="mt-6 mb-3 font-bold">Rezervirana orodja</h4>{activeReservations.filter(r=>r.workOrderId===selectedOrder.id).length===0?<p className="text-sm text-[#92a4bd]">Ni rezerviranih orodij.</p>:<div className="space-y-2">{activeReservations.filter(r=>r.workOrderId===selectedOrder.id).map(r=>{const t=tools.find(x=>x.id===r.toolId);const op=selectedOrder.operations.find(x=>x.id===r.operationId);return <div key={r.id} className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-[#293448] p-3"><div><p className="font-bold">{t?.name} <span className="font-normal text-[#92a4bd]">{t?.size}</span></p><p className="text-xs text-[#92a4bd]">{op?.name}</p></div><div className="flex flex-wrap items-center gap-2"><Tag value={r.status} label={reservationNames[r.status]}/>{r.status==='reserved'&&<button disabled={busy} className="btn secondary !min-h-9" onClick={()=>void mutate(()=>request(`/tool-reservations/${r.id}`,'PUT',{status:'in_use'}))}>V uporabo</button>}<button disabled={busy} className="btn danger !min-h-9" onClick={()=>void mutate(()=>request(`/tool-reservations/${r.id}`,'DELETE'))}>Sprosti</button></div></div>})}</div>}</section>
  <section className="card p-5 md:p-7"><h3 className="section-title mb-4">✎ Opombe</h3><textarea className="control min-h-32" placeholder="Vpiši opombe o izdelavi, meritve, navodila ..." value={noteDraft} onChange={e=>setNoteDraft(e.target.value)}/><div className="mt-3 flex justify-end"><button className="btn primary" disabled={busy} onClick={()=>void patchOrder({notes:noteDraft})}>Shrani opombe</button></div></section>
 </>:page==='dashboard'?<><div className="flex flex-wrap items-end justify-between gap-3"><div><div className="text-[11px] font-bold uppercase tracking-widest text-[#71a6ff]">Pregled delavnice</div><h2 className="mt-1 text-2xl font-extrabold tracking-tight md:text-3xl">Dobrodošli nazaj 👋</h2><p className="mt-1 text-sm text-[#92a4bd]">Vse pomembne informacije o delu na enem mestu.</p></div><button className="btn primary" onClick={()=>{setEditing(null);setModal('order')}}>＋ Nov delovni nalog</button></div><div className="grid grid-cols-2 gap-2 sm:gap-3 lg:grid-cols-4">{[{label:'Vsi nalogi',value:orders.length,ico:'▤',color:'text-[#71a6ff] bg-[#142747]'},{label:'Aktivni nalogi',value:orders.filter(o=>o.status==='in_progress').length,ico:'◉',color:'text-[#ffc27a] bg-[#422f1d]'},{label:'Zaključeni nalogi',value:orders.filter(o=>o.status==='done').length,ico:'✓',color:'text-[#62dba8] bg-[#16372d]'},{label:'Prosta orodja',value:tools.filter(t=>toolStatus(t)==='available').length,ico:'⚒',color:'text-purple-600 bg-purple-50'}].map(s=><div key={s.label} className="card p-4 md:p-5"><div className={'mb-4 flex h-10 w-10 items-center justify-center rounded-xl text-xl '+s.color}>{s.ico}</div><div className="text-2xl font-extrabold md:text-3xl">{s.value}</div><div className="mt-1 text-xs font-medium text-[#92a4bd]">{s.label}</div></div>)}</div><div className="grid gap-3 sm:grid-cols-3"><div className="card p-5"><p className="text-xs text-[#a4b2c6]">Predvideni stroški obdelav</p><p className="mt-2 text-2xl font-extrabold text-[#91baff]">{eur(orders.reduce((sum,w)=>sum+orderCost(w,machines),0))}</p></div><div className="card p-5"><p className="text-xs text-[#a4b2c6]">Dejanski obračun obdelav</p><p className="mt-2 text-2xl font-extrabold">{eur(orders.reduce((sum,w)=>sum+orderCost(w,machines,true),0))}</p></div><div className="card p-5"><p className="text-xs text-[#a4b2c6]">Evidentirani stroji</p><p className="mt-2 text-2xl font-extrabold">{machines.length}</p></div></div><div className="flex items-center justify-between"><h3 className="section-title">Najnovejši delovni nalogi</h3><button className="text-xs font-bold text-[#71a6ff]" onClick={()=>changePage('orders')}>Prikaži vse →</button></div>{orders.length?<div className="grid gap-4 lg:grid-cols-2">{[...orders].reverse().slice(0,6).map(w=><WorkCard key={w.id} w={w} onClick={()=>setSelected(w.id)}/>)}</div>:<Empty icon="▤" title="Ni še ustvarjenih delovnih nalogov" desc="Začni z novim nalogom in organiziraj delo v delavnici." action={<button className="btn primary" onClick={()=>{setEditing(null);setModal('order')}}>＋ Nov delovni nalog</button>}/>}</>:
 page==='orders'||page==='archive'?<><div className="flex flex-wrap items-center justify-between gap-3"><div><h2 className="text-2xl font-extrabold">{page==='archive'?'Arhiv nalogov':'Delovni nalogi'}</h2><p className="mt-1 text-sm text-[#92a4bd]">{page==='archive'?'Pregled zaključenih nalogov':'Upravljaj proizvodne naloge in njihov napredek.'}</p></div>{page==='orders'&&<button className="btn primary" onClick={()=>{setEditing(null);setModal('order')}}>＋ Nov nalog</button>}</div><div className="flex flex-wrap gap-3"><input className="control min-w-0 flex-[1_1_220px]" placeholder="⌕ Poišči delovni nalog ..." value={search} onChange={e=>setSearch(e.target.value)}/><select className="control w-full sm:!w-[180px]" value={filter} onChange={e=>setFilter(e.target.value)}><option value="all">Vsa stanja</option>{Object.entries(statusNames).map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></div>{filteredOrders.length?<div className="grid gap-4 lg:grid-cols-2">{filteredOrders.map(w=><WorkCard key={w.id} w={w} onClick={()=>setSelected(w.id)}/>)}</div>:<Empty icon="▤" title="Ni najdenih nalogov" desc="Spremeni iskanje ali ustvari nov delovni nalog."/>}</>:
 (['schedules','quotes','products','inspections','employees','drawings'] as Page[]).includes(page)?<ProModules mode={page as 'schedules'|'quotes'|'products'|'inspections'|'employees'|'drawings'} orders={orders} machines={machines} onOrderCreated={()=>void refresh()}/>:page==='materials'?<><div className="flex flex-wrap items-center justify-between gap-3"><div><h2 className="text-2xl font-extrabold">Materiali</h2><p className="mt-1 text-sm text-[#92a4bd]">Evidenca materiala in zalog.</p></div><button className="btn primary" onClick={()=>{setEditing(null);setModal('material')}}>＋ Dodaj material</button></div><input className="control" placeholder="⌕ Poišči material ..." value={search} onChange={e=>setSearch(e.target.value)}/>{filteredMaterials.length?<div className="grid gap-4 lg:grid-cols-2">{filteredMaterials.map(m=><div key={m.id} className="card p-5"><div className="flex items-start justify-between gap-3"><div className="flex gap-3"><div className="flex h-11 w-11 items-center justify-center rounded-xl bg-[#292342] text-xl text-[#b4a7ff]">▧</div><div><p className="font-extrabold">{m.name}</p><p className="mt-1 text-xs text-[#92a4bd]">{m.standard||m.shape} · {m.dimensions||'Brez dimenzij'}</p></div></div><Tag value={m.quantity>0?'available':'unavailable'} label={m.quantity>0?'Na zalogi':'Ni zaloge'}/></div><div className="mt-5 flex items-center justify-between border-t border-[#293448] pt-4"><div><div className="text-xs text-[#92a4bd]">Razpoložljiva količina</div><div className="text-xl font-extrabold">{m.quantity} <span className="text-sm font-medium text-[#92a4bd]">{m.unit}</span></div></div><div className="flex gap-2"><button className="btn secondary" onClick={()=>{setEditing(m.id);setModal('material')}}>Uredi</button><button className="btn danger" disabled={busy} onClick={()=>void deleteItem('materials',m.id)}>✕</button></div></div></div>)}</div>:<Empty icon="▧" title="Ni dodanih materialov" desc="Dodaj prvi material in spremljaj zalogo." action={<button className="btn primary" onClick={()=>{setEditing(null);setModal('material')}}>Dodaj material</button>}/>}</>:
 page==='machines'?<><div className="flex flex-wrap items-center justify-between gap-3"><div><h2 className="text-2xl font-extrabold">Strojni park</h2><p className="mt-1 text-sm text-[#92a4bd]">CNC stružnice, CNC rezkalni stroji, brusilniki, žage in urne postavke.</p></div><button className="btn primary" onClick={()=>{setEditing(null);setModal('machine')}}>＋ Dodaj stroj</button></div><div className="flex flex-wrap gap-3"><input className="control min-w-0 flex-[1_1_220px]" placeholder="⌕ Išči po strojnem parku ..." value={search} onChange={e=>setSearch(e.target.value)}/><select className="control w-full sm:!w-[190px]" value={filter} onChange={e=>setFilter(e.target.value)}><option value="all">Vsa stanja</option>{Object.entries(toolNames).map(([v,l])=><option key={v} value={v}>{l}</option>)}<option value="in_use">V obdelavi</option></select></div>{filteredMachines.length?<div className="grid gap-4 lg:grid-cols-2">{filteredMachines.map(m=><div className="card p-5" key={m.id}><div className="flex items-start justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-wider text-[#71a6ff]">{machineCategories[m.category]} · {m.code||'Brez oznake'}</p><h3 className="mt-2 text-lg font-extrabold">{m.name}</h3><p className="mt-1 text-xs text-[#a4b2c6]">{m.manufacturer||'Proizvajalec ni naveden'}</p></div><Tag value={machineStatus(m)} label={machineStatus(m)==='in_use'?'V obdelavi':toolNames[m.condition]}/></div><p className="mt-3 text-xs text-[#a4b2c6]">{machineUsage(m.id)?`V obdelavi: ${machineUsage(m.id)?.number} · ${machineUsage(m.id)?.product}`:'Stroj ni zaseden z aktivno operacijo.'}</p><div className="mt-5 rounded-xl bg-[#142747] p-4"><p className="text-xs text-[#91baff]">Urna postavka obdelave</p><p className="mt-1 text-2xl font-extrabold text-[#c7ddff]">{eur(m.hourlyRate)} <span className="text-xs">/ h</span></p></div><div className="mt-4 flex justify-end gap-2"><button className="btn secondary" onClick={()=>{setEditing(m.id);setModal('machine')}}>Uredi</button><button disabled={busy} className="btn danger" onClick={()=>void deleteItem('machines',m.id)}>Izbriši</button></div></div>)}</div>:<Empty icon="⚙" title="Ni dodanih strojev" desc="Dodaj CNC stružnico, CNC rezkalnik, žago ali brusilni stroj." action={<button className="btn primary" onClick={()=>{setEditing(null);setModal('machine')}}>Dodaj prvi stroj</button>}/>}</>:
 <><div className="flex flex-wrap items-center justify-between gap-3"><div><h2 className="text-2xl font-extrabold">Orodja</h2><p className="mt-1 text-sm text-[#92a4bd]">Razpoložljivost in evidenca orodij.</p></div><button className="btn primary" onClick={()=>{setEditing(null);setModal('tool')}}>＋ Dodaj orodje</button></div><div className="flex flex-wrap gap-3"><input className="control min-w-0 flex-[1_1_220px]" placeholder="⌕ Poišči orodje ..." value={search} onChange={e=>setSearch(e.target.value)}/><select className="control w-full sm:!w-[190px]" value={filter} onChange={e=>setFilter(e.target.value)}><option value="all">Vsa orodja</option><option value="available">Na voljo</option><option value="reserved">Rezervirano</option><option value="in_use">V uporabi</option><option value="maintenance">V vzdrževanju</option><option value="unavailable">Ni na voljo</option></select></div>{filteredTools.length?<div className="grid gap-4 lg:grid-cols-2">{filteredTools.map(t=>{const r=getReservation(t.id);const w=r?orders.find(o=>o.id===r.workOrderId):null;const st=toolStatus(t);return <div key={t.id} className="card p-5"><div className="flex items-start justify-between gap-3"><div className="flex gap-3"><div className="flex h-11 w-11 items-center justify-center rounded-xl bg-[#142747] text-xl text-[#71a6ff]">⚒</div><div><div className="font-extrabold">{t.name}</div><div className="mt-1 text-xs text-[#92a4bd]">{t.category} · {t.size||t.specification||'Brez oznake'}</div></div></div><Tag value={st} label={st==='available'?toolNames.available:st==='reserved'||st==='in_use'?reservationNames[st]:toolNames[st]}/></div><div className="mt-4 text-xs text-[#92a4bd]">{t.location?'Lokacija: '+t.location:'Lokacija ni določena'}{w?' · '+w.number+' ('+w.product+')':''}</div><div className="mt-4 flex justify-end gap-2 border-t border-[#293448] pt-3"><button className="btn secondary" onClick={()=>{setEditing(t.id);setModal('tool')}}>Uredi</button>{r&&<button className="btn secondary" disabled={busy} onClick={()=>void mutate(()=>request(`/tool-reservations/${r.id}`,'DELETE'))}>Sprosti</button>}<button className="btn danger" disabled={busy} onClick={()=>void deleteItem('tools',t.id)}>✕</button></div></div>})}</div>:<Empty icon="⚒" title="Ni najdenih orodij" desc="Dodaj orodje ali spremeni iskalne filtre."/>}</>}
 </main></div>
 {mobileMenuOpen&&<div className="mobile-menu-overlay fixed inset-0 z-40 bg-black/75 md:hidden" onClick={()=>setMobileMenuOpen(false)}><div className="mobile-menu-panel absolute bottom-[calc(70px+env(safe-area-inset-bottom))] left-3 right-3 max-h-[70dvh] overflow-y-auto rounded-2xl border border-[#2c3a51] bg-[#141d29] p-4 shadow-2xl" onClick={e=>e.stopPropagation()}><div className="mb-3 flex items-center justify-between"><strong>Vsi moduli</strong><button className="btn ghost" onClick={()=>setMobileMenuOpen(false)}>Zapri ✕</button></div><div className="grid grid-cols-3 gap-2">{(Object.keys(nav) as Page[]).map(p=><button key={p} className={'flex min-h-[74px] flex-col items-center justify-center gap-1 rounded-xl px-1 text-center text-xs font-semibold '+(page===p?'bg-[#1d3b68] text-[#a8cbff]':'bg-[#1c293a] text-[#d2deef]')} onClick={()=>changePage(p)}><span className="text-2xl">{icon[p]}</span>{nav[p]}</button>)}</div></div></div>}
 <nav className="mobile-bottom fixed inset-x-0 bottom-0 z-50 flex items-stretch justify-around gap-1 border-t border-[#293448] bg-[#111923] px-2 pt-2 md:hidden" aria-label="Glavna navigacija">{(['dashboard','orders','schedules','machines'] as Page[]).map(p=><button key={p} className={'mobile-nav-item flex min-w-0 flex-1 flex-col items-center justify-center gap-0.5 rounded-xl px-1 py-1 text-[10px] font-semibold '+(p===page?'bg-[#1b3659] text-[#a8cbff]':'text-[#9db0c9]')} onClick={()=>changePage(p)}><span className="text-xl leading-6">{icon[p]}</span><span className="truncate">{nav[p]}</span></button>)}<button className={'mobile-nav-item flex min-w-0 flex-1 flex-col items-center justify-center gap-0.5 rounded-xl px-1 py-1 text-[10px] font-semibold '+(mobileMenuOpen||!(['dashboard','orders','schedules','machines'] as Page[]).includes(page)?'bg-[#1b3659] text-[#a8cbff]':'text-[#9db0c9]')} onClick={()=>setMobileMenuOpen(v=>!v)} aria-expanded={mobileMenuOpen} aria-label="Odpri vse module"><span className="text-xl leading-6">☷</span><span>Več</span></button></nav>
 {modal==='order'&&<OrderForm original={editingOrder} onSave={v=>void saveOrder(v)} onClose={()=>{setModal(null);setEditing(null)}} busy={busy}/>} {modal==='material'&&<MaterialForm original={editingMaterial} onSave={v=>void saveMaterial(v)} onClose={()=>{setModal(null);setEditing(null)}} busy={busy}/>} {modal==='tool'&&<ToolForm original={editingTool} onSave={v=>void saveTool(v)} onClose={()=>{setModal(null);setEditing(null)}} busy={busy}/>} {modal==='machine'&&<MachineForm original={editingMachine} onSave={v=>void saveMachine(v)} onClose={()=>{setModal(null);setEditing(null)}} busy={busy}/>} {modal==='editOperation'&&currentOp&&<OperationEditForm op={currentOp} machines={machines} onSave={v=>void (async()=>{const ok=await updateOp(currentOp.id,v);if(ok)setModal(null)})()} onClose={()=>{setModal(null);setEditingOperation(null)}} busy={busy}/>} {modal==='operation'&&<OperationForm onSave={v=>void addOperation(v)} onClose={()=>setModal(null)}/>}
 </div>;
}
